import React, { useState, useEffect } from 'react';
import { Container, Row, Col, Card, Table, Button, Modal, Form, Badge } from 'react-bootstrap';
import { toast } from 'react-toastify';
import { adminAPI } from '../../services/api';

const ManageZoom = () => {
  const [zoomLinks, setZoomLinks] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [editMode, setEditMode] = useState(false);
  const [currentZoom, setCurrentZoom] = useState(null);
  const [formData, setFormData] = useState({
    zoom_account_name: '',
    zoom_email: '',
    zoom_link: '',
    meeting_id: '',
    passcode: '',
    is_active: true
  });

  useEffect(() => {
    fetchZoomLinks();
  }, []);

  const fetchZoomLinks = async () => {
    try {
      setLoading(true);
      console.log('🔍 Fetching zoom links...');
      
      const response = await adminAPI.getZoomLinks();
      console.log('🔗 Zoom links response:', response);
      
      // Handle response data with validation
      let zoomLinksData = [];
      if (response.data) {
        if (Array.isArray(response.data)) {
          zoomLinksData = response.data;
        } else if (response.data.data && Array.isArray(response.data.data)) {
          zoomLinksData = response.data.data;
        }
      }

      // Ensure it's an array
      if (!Array.isArray(zoomLinksData)) {
        console.warn('⚠️ Zoom links is not an array, setting to empty array');
        zoomLinksData = [];
      }

      console.log('📋 Processed zoom links:', zoomLinksData);
      setZoomLinks(zoomLinksData);
    } catch (error) {
      console.error('❌ Error fetching zoom links:', error);
      console.error('Error details:', error.response?.data);
      
      // Set empty array on error
      setZoomLinks([]);
      
      toast.error('Gagal memuat data zoom links');
    } finally {
      setLoading(false);
    }
  };

  const handleOpenModal = (zoom = null) => {
    if (zoom) {
      setEditMode(true);
      setCurrentZoom(zoom);
      setFormData({
        zoom_account_name: zoom.zoom_account_name,
        zoom_email: zoom.zoom_email,
        zoom_link: zoom.zoom_link,
        meeting_id: zoom.meeting_id,
        passcode: zoom.passcode,
        is_active: zoom.is_active
      });
    } else {
      setEditMode(false);
      setCurrentZoom(null);
      setFormData({
        zoom_account_name: '',
        zoom_email: '',
        zoom_link: '',
        meeting_id: '',
        passcode: '',
        is_active: true
      });
    }
    setShowModal(true);
  };

  const handleCloseModal = () => {
    setShowModal(false);
    setEditMode(false);
    setCurrentZoom(null);
  };

  const handleChange = (e) => {
    const value = e.target.type === 'checkbox' ? e.target.checked : e.target.value;
    setFormData({
      ...formData,
      [e.target.name]: value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    try {
      if (editMode) {
        await adminAPI.updateZoomLink(currentZoom.id, formData);
        toast.success('Zoom link berhasil diperbarui!');
      } else {
        await adminAPI.createZoomLink(formData);
        toast.success('Zoom link berhasil ditambahkan!');
      }
      
      fetchZoomLinks();
      handleCloseModal();
    } catch (error) {
      console.error('Error saving zoom link:', error);
      toast.error('Gagal menyimpan zoom link');
    }
  };

  const handleDelete = async (id) => {
    if (window.confirm('Apakah Anda yakin ingin menghapus zoom link ini?')) {
      try {
        await adminAPI.deleteZoomLink(id);
        toast.success('Zoom link berhasil dihapus!');
        fetchZoomLinks();
      } catch (error) {
        console.error('Error deleting zoom link:', error);
        toast.error('Gagal menghapus zoom link');
      }
    }
  };

  if (loading) {
    return (
      <div className="text-center py-5">
        <div className="spinner-border" role="status">
          <span className="visually-hidden">Loading...</span>
        </div>
      </div>
    );
  }

  return (
    <Container fluid>
      {/* Header */}
      <Row className="mb-4">
        <Col>
          <h2>Kelola Zoom Accounts</h2>
          <p className="text-muted">Manage zoom accounts untuk booking meeting</p>
        </Col>
        <Col xs="auto">
          <Button variant="primary" onClick={() => handleOpenModal()}>
            <i className="fas fa-plus me-2"></i>
            Tambah Zoom Account
          </Button>
        </Col>
      </Row>

      {/* Zoom Links Table */}
      <Row>
        <Col>
          <Card>
            <Card.Body>
              {zoomLinks.length > 0 ? (
                <Table responsive hover>
                  <thead>
                    <tr>
                      <th>Account Name</th>
                      <th>Email</th>
                      <th>Meeting ID</th>
                      <th>Zoom Link</th>
                      <th>Status</th>
                      <th>Aksi</th>
                    </tr>
                  </thead>
                  <tbody>
                    {zoomLinks.map((zoom) => (
                      <tr key={zoom.id}>
                        <td>
                          <strong>{zoom.zoom_account_name}</strong>
                        </td>
                        <td>{zoom.zoom_email}</td>
                        <td>
                          <code>{zoom.meeting_id}</code>
                          <br />
                          <small className="text-muted">Passcode: {zoom.passcode}</small>
                        </td>
                        <td>
                          <a 
                            href={zoom.zoom_link} 
                            target="_blank" 
                            rel="noopener noreferrer"
                            className="text-truncate d-inline-block"
                            style={{ maxWidth: '200px' }}
                          >
                            {zoom.zoom_link}
                          </a>
                        </td>
                        <td>
                          <Badge bg={zoom.is_active ? 'success' : 'secondary'}>
                            {zoom.is_active ? 'Aktif' : 'Nonaktif'}
                          </Badge>
                        </td>
                        <td>
                          <div className="btn-group">
                            <Button
                              variant="outline-primary"
                              size="sm"
                              onClick={() => handleOpenModal(zoom)}
                            >
                              <i className="fas fa-edit"></i>
                            </Button>
                            <Button
                              variant="outline-danger"
                              size="sm"
                              onClick={() => handleDelete(zoom.id)}
                            >
                              <i className="fas fa-trash"></i>
                            </Button>
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </Table>
              ) : (
                <div className="text-center py-5">
                  <i className="fas fa-video fa-3x text-muted mb-3"></i>
                  <h5>Belum ada zoom account</h5>
                  <p className="text-muted">Tambahkan zoom account untuk dapat digunakan dalam booking</p>
                  <Button variant="primary" onClick={() => handleOpenModal()}>
                    Tambah Zoom Account
                  </Button>
                </div>
              )}
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* Add/Edit Modal */}
      <Modal show={showModal} onHide={handleCloseModal} size="lg">
        <Modal.Header closeButton>
          <Modal.Title>
            {editMode ? 'Edit Zoom Account' : 'Tambah Zoom Account'}
          </Modal.Title>
        </Modal.Header>
        <Form onSubmit={handleSubmit}>
          <Modal.Body>
            <Row>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>Account Name *</Form.Label>
                  <Form.Control
                    type="text"
                    name="zoom_account_name"
                    value={formData.zoom_account_name}
                    onChange={handleChange}
                    placeholder="Contoh: BRI Meeting Room 1"
                    required
                  />
                </Form.Group>
              </Col>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>Email Zoom *</Form.Label>
                  <Form.Control
                    type="email"
                    name="zoom_email"
                    value={formData.zoom_email}
                    onChange={handleChange}
                    placeholder="meeting1@bri.co.id"
                    required
                  />
                </Form.Group>
              </Col>
            </Row>

            <Row>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>Meeting ID *</Form.Label>
                  <Form.Control
                    type="text"
                    name="meeting_id"
                    value={formData.meeting_id}
                    onChange={handleChange}
                    placeholder="123-456-789"
                    required
                  />
                </Form.Group>
              </Col>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>Passcode *</Form.Label>
                  <Form.Control
                    type="text"
                    name="passcode"
                    value={formData.passcode}
                    onChange={handleChange}
                    placeholder="password123"
                    required
                  />
                </Form.Group>
              </Col>
            </Row>

            <Form.Group className="mb-3">
              <Form.Label>Zoom Link *</Form.Label>
              <Form.Control
                type="url"
                name="zoom_link"
                value={formData.zoom_link}
                onChange={handleChange}
                placeholder="https://zoom.us/j/123456789?pwd=..."
                required
              />
            </Form.Group>

            <Form.Group className="mb-3">
              <Form.Check
                type="checkbox"
                name="is_active"
                checked={formData.is_active}
                onChange={handleChange}
                label="Aktif (dapat digunakan untuk booking)"
              />
            </Form.Group>
          </Modal.Body>
          <Modal.Footer>
            <Button variant="secondary" onClick={handleCloseModal}>
              Batal
            </Button>
            <Button variant="primary" type="submit">
              {editMode ? 'Update' : 'Simpan'}
            </Button>
          </Modal.Footer>
        </Form>
      </Modal>
    </Container>
  );
};

export default ManageZoom;
